//! The data of the game embedded in the application, generated by `tools/game-data` (see
//! `docs/game-data.md`): the stats of each modifier line, with their trade ids.
//!
//! It reads the lines of every copied item: like the parser, it must never panic, and the
//! lints below rule out what can panic outside the tests.
#![cfg_attr(
    not(test),
    deny(
        clippy::indexing_slicing,
        clippy::string_slice,
        clippy::unwrap_used,
        clippy::expect_used,
        clippy::panic,
        clippy::unreachable,
        clippy::todo,
        clippy::unimplemented
    )
)]

mod lines;
mod stats;

pub use lines::modifier_stats;
pub use stats::TradeGroup;
